-- [resumo]
-- genericRpg: RPG genérico.
-- Usa vec2, lerp, check_colision (via fget/mget) e erroLibary; wrappers lpv2
-- (lerp de vec2), sprv2 e mapv2. A arte fica nos .kra/.png ao lado (sprs, tiles).
-- Nota: addPath usa H:/Meu Drive/... (caminho do Windows antigo).
-- ------------------------------------------------------------

errors={}
function check_error(functions, msg1, msg2)
	local sucess, ErroMensage = pcall(function()
		functions()
	end)

	if sucess then
		return msg1
	else
		table.insert(errors, {msg = ErroMensage})
		return msg2 or "erro"
	end
end
function return_error(ErroMensage)
	table.insert(errors, {msg = ErroMensage})
end

maindir="H:/Meu Drive/tic-80/appdata/"
function addPath(dir)
	package.path = package.path ..";" .. maindir.. dir .. "/?.lua"
end

addPath("libraries")
addPath("libraries/code_of_TIC80")

check_error(
	function()
		v2 = require("vec2")
		lp = require("lerp")

		collision = require("check_colision")

		collision.SetDetectetionFunctions(
			function(x, y, s)
				return fget(mget(x,y),s)
			end
		)
	end,
	"arquivos importados com sucesso",
	"erro ao importar os arquivos"
)

function lpv2(a,b,t)
	return v2(
		lp(a.x, b.x, t),
		lp(a.y, b.y, t)
	)
end

function sprv2(spr__, pos, colorkey, scale, flip, rotate, WH)
	if type(pos)=="table" and type(WH)=="table" then
		spr(
			spr__ or 240,
			pos.x or 0,
			pos.y or 0,
			colorkey or 0,
			scale or 0,
			flip or 0,
			rotate or 0,
			WH.x or 0,
			WH.y or 0
		)
	else
		return_error("pos or wh not is v2")
	end
end

function mapv2(poscel, size, pos, colorkey, scale, remap)
	local poscel = poscel or v2()
	local size = size or v2()
	local pos = pos or v2()
	if type(poscel)=="table" and type(size)=="table" and type(pos)=="table" then
		map(
			poscel.x, poscel.y,
			size.x, size.y,
			pos.x, pos.y,
			colorkey,
			scale or 1,
			remap or false
		)
	else
		return_error("poscel or size or pos")
	end
end

plr = {
	type = "player",
	sprites = {
		["default"]=256
	},
	diretion = 0,
	pos = v2(),
	vel = v2(),
	spd = 1.25,
	setpos = function(s, pos)
		s.pos = pos
	end,
	move = function(s)
		
		if btn(0) then s.vel.y = -1
		elseif btn(1) then s.vel.y = 1
		else s.vel.y = 0 end
		
		if btn(2) then
			s.vel.x = -1
			s.diretion = 1
		elseif btn(3) then
			s.vel.x = 1
			s.diretion = 0
		else s.vel.x = 0 end

		local moviment = 0
		if btn(0) or btn(1) or btn(2) or btn(3) then moviment=1 end
		local a = math.atan(s.vel.y, s.vel.x)
		local newvel = v2(math.cos(a)*moviment*s.spd, math.sin(a)*moviment*s.spd)
		
		s.pos = s.pos + newvel
	end,
	draw = function(s)
		local __spr = s.sprites["default"]

		sprv2(__spr, s.pos-cam.pos, 0, 1, s.diretion, 0, v2(4,4))

	end
}

cam = {
	pos = v2(),
	update = function(s, target)
		s.pos = lpv2(s.pos, target.pos-v2(120, 68)+v2(2*8,2*8), 0.05)
	end
}

map_={
	remap = false,
	draw = function(s)
		local p = cam.pos
		local p1 = v2(p.x//8, p.y//8)
		local sv2 = v2(p.x%8, p.y%8)
		mapv2(p1, v2(31,19), -sv2-v2(8,8), 0, 1, s.remap)
	end
}


function TIC()
	plr:move()
	cam:update(plr)
	
	poke(0x03FF8, 1)
	cls(1)

	map_:draw()
	plr:draw()
	
end

function encerramentoDoPrograma()
	for i, v in ipairs(errors) do
		trace(v.msg)
	end
end

debug.sethook(encerramentoDoPrograma, "l")



